// Compile every MDX file under src/content/ into src/generated/posts.ts.
//
//   bun run build:content
//
// The site is fully static: this runs before `bun dev` and `bun run build`, and the
// generated file is committed so `tsc --noEmit` works on a fresh checkout (same
// arrangement as src/styles.css).
//
// Frontmatter:
//
//   ---
//   id: 1                 # shared by every language version of one article
//   lang: zh              # zh | en
//   title: 标题
//   date: 2026-08-28
//   tags: [Bun, React]
//   excerpt: 摘要
//   ---

import path from "node:path";
import { compilePost, fail, type CompiledPost } from "./mdx.ts";

const CONTENT_DIR = "src/content";
const OUTPUT = "src/generated/posts.ts";

const files = (
	await Array.fromAsync(new Bun.Glob(`${CONTENT_DIR}/**/*.mdx`).scan("."))
).sort();

if (!files.length) {
	fail(`no .mdx files found under ${CONTENT_DIR}/`);
}

const posts: CompiledPost[] = [];
const seen = new Map<string, string>();

for (const file of files) {
	const post = await compilePost(file);
	const key = `${post.id}.${post.lang}`;
	const previous = seen.get(key);
	if (previous) {
		fail(`post ${post.id} has two ${post.lang} versions: ${previous} and ${file}`);
	}
	seen.set(key, file);
	posts.push(post);
}

// Newest first, then by id, so the list order never depends on file names.
posts.sort(
	(a, b) => b.date.localeCompare(a.date) || b.id - a.id || a.lang.localeCompare(b.lang),
);

const source = `// AUTO-GENERATED by scripts/build-content.ts — do not edit by hand.
// Edit the MDX under src/content/ and run \`bun run build:content\`.

export interface GeneratedTocItem {
	id: string;
	text: string;
	level: number;
}

export interface GeneratedPost {
	id: number;
	lang: "zh" | "en";
	title: string;
	date: string;
	tags: string[];
	excerpt: string;
	readingTime: number;
	html: string;
	toc: GeneratedTocItem[];
}

export const POSTS: GeneratedPost[] = ${JSON.stringify(posts, null, "\t")};
`;

await Bun.write(OUTPUT, source);

const articles = new Set(posts.map((post) => post.id)).size;
console.log(
	`✓ ${posts.length} translations across ${articles} articles → ${path.normalize(OUTPUT)}`,
);
for (const post of posts) {
	console.log(
		`  ${post.id} ${post.lang}  ${post.readingTime} min  ${post.toc.length} headings  ${post.title}`,
	);
}
